/* Personal views and reversible feedback. Predicates are pure for regression tests. */
function viewMatches(e,v,saved){
 if(!v)return true;
 const text=[e.title,e.summary,e.titleZh,e.summaryZh].filter(Boolean).join(' ').toLowerCase();
 const types=e.providerKind||e.type!=='news'?'market':'news';
 return (!v.type||v.type==='all'||v.type===types||v.type===e.type)&&(!v.channels?.length||v.channels.includes(e.channel))&&(!v.topics?.length||v.topics.includes(e.topic)||v.topics.includes(e.providerKind))&&(!v.projectIds?.length||(e.projectIds||[e.p]).some(p=>v.projectIds.includes(p)))&&(!v.include?.length||v.include.some(w=>text.includes(w.toLowerCase())))&&(!v.exclude?.some(w=>text.includes(w.toLowerCase())))&&(!v.savedOnly||saved)&&(!v.minLength||(e.summary||'').length>=v.minLength);
}
function visibleProjects(e,feedback){return (e.projectIds||[e.p]).filter(p=>!feedback.some(f=>f.kind==='unrelated'&&f.projectId===p&&f.eventKey===(e.url||String(e.id))))}
function feedbackReason(e,feedback,pid,followed){
 const projects=visibleProjects(e,feedback);
 if(pid?!projects.includes(pid):!projects.some(p=>followed.includes(p)))return '已标记与项目无关';
 if(feedback.some(f=>f.kind==='source'&&f.value===(e.sourceUrl||e.source)))return '已静音来源';
 if(feedback.some(f=>f.kind==='topic'&&f.value===(e.topic||e.providerKind||'项目资讯')&&(!f.projectId||projects.includes(f.projectId))))return '已减少此类内容';
 return '';
}
if(typeof document!=='undefined'){
 const presets=[{id:'official',name:'官方重要进展',channels:['official','x','team'],include:['mainnet','launch','release','主网','产品','代币','tokenomics','buyback']},{id:'listing',name:'交易所动态',topics:['交易所动态','listing']},{id:'risk',name:'我的持仓风险',include:['hack','exploit','delay','outage','漏洞','攻击','延期','暂停','停机']},{id:'market',name:'市场异动',type:'market'},{id:'research',name:'周末研究',savedOnly:true,minLength:300}];
 let chosen='',extensionCache=new Map(),pending=new Set();
 const views=()=>[...presets,...(state.readerViews||[])];
 const activeView=()=>views().find(v=>v.id===chosen);
 const oldEligible=readerEligible;readerEligible=function(e){return oldEligible(e)&&!feedbackReason(e,state.readerFeedback||[],null,state.projects)};
 belongs=function(e,pid){return visibleProjects(e,state.readerFeedback||[]).includes(pid)};
 const oldFiltered=filteredEvents;filteredEvents=function(){return oldFiltered().filter(e=>(!state.project||belongs(e,state.project))&&viewMatches(e,activeView(),savedEvent(e)))};
 const oldCard=eventCard;eventCard=function(e){const ids=visibleProjects(e,state.readerFeedback||[]);let card=oldCard({...e,projectIds:ids});return card.replace('<div class="event-bottom">',`<div class="event-bottom"><button class="text-button" data-feedback-event="${e.id}" aria-label="调整这条资讯">调整</button>`)};
 async function extension(pid,force=false){if(pending.has(pid))return;const old=extensionCache.get(pid);if(!force&&old&&Date.now()-old.loadedAt<60000)return;pending.add(pid);try{const r=await fetch('/api/extensions?project='+encodeURIComponent(pid));if(!r.ok)throw Error('项目扩展暂不可用');extensionCache.set(pid,{...await r.json(),loadedAt:Date.now()})}catch{extensionCache.set(pid,{...old,error:true,loadedAt:Date.now()})}finally{pending.delete(pid);if(state.project===pid)render()}}
 const statuses={missing_credential:'DefiLlama API 未配置：可手动录入带来源的日程',error:'供应方查询失败，保留缓存；旧计划需要重新核对',ok:'DefiLlama 已更新'};
 function calendarPanel(p,x){const history=(x?.calendar?.items||[]).filter(i=>i.p===p.id&&i.kind==='funding').sort((a,b)=>b.at-a.at);
  return `<section class="project-section project-calendar"><div class="project-section-title"><h3>项目资料与订阅</h3><button class="secondary" data-sources-manage="${p.id}">免费信源与额度设置</button></div><details><summary>融资披露历史 · ${history.length} 条</summary>${history.map(i=>calendarItem(i)).join('')||'<p>暂无已收录融资披露。</p>'}<button class="text-button" data-calendar-add="${p.id}">录入融资披露</button> · <button class="text-button" data-calendar-map="${p.id}">关联融资数据</button></details></section>`;
 }
 function calendarItem(i){return `<article class="calendar-item"><strong>${escapeHtml(i.title)}</strong><p>${escapeHtml(i.precision==='day'?new Date(i.at).toLocaleDateString('zh-CN'):formatTime(i.at))}</p><small>${escapeHtml(i.source)} · 采集 ${formatTime(i.checkedAt)}</small> <a href="${escapeHtml(safeUrl(i.url))}" target="_blank" rel="noopener noreferrer">核对来源 ↗</a>${i.origin==='manual'?` <button class="text-button" data-calendar-remove="${i.id}">移除</button>`:''}</article>`}
 const prev=render;render=function(){prev();document.querySelector('#personal-views')?.remove();if(state.view!=='rules'){
  $('#feed-controls').insertAdjacentHTML('afterbegin',`<div id="personal-views"><label>我的情报视图 <select id="reader-view"><option value="">全部资讯</option>${views().map(v=>`<option value="${escapeHtml(v.id)}" ${chosen===v.id?'selected':''}>${escapeHtml(v.name)}</option>`).join('')}</select></label><button class="text-button" data-new-view>保存 / 编辑视图</button><button class="text-button" data-manage-feedback>降噪管理 (${state.readerFeedback?.length||0})</button>${activeView()?'<small>与下方筛选条件共同生效</small>':''}</div>`);
 }
 if(state.project){const p=catalog.find(p=>p.id===state.project);document.querySelector('.project-calendar')?.remove();const chart=document.querySelector('.linked-chart');chart?.insertAdjacentHTML('afterend',calendarPanel(p,extensionCache.get(p.id)));extension(p.id)}
 };
 const priorChartNews=openChartNews;openChartNews=function(index){chosen='';priorChartNews(index)};
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="clear"],[data-chart-open]'))chosen=''},true);
 const priorProjectForm=projectForm;projectForm=function(p={}){priorProjectForm(p);$('#new-project-form .modal-footer')?.insertAdjacentHTML('beforebegin','<p class="module-note">保存后会探测官网的 RSS、博客、GitHub Release 和公告频道链接。发现的候选在项目页「免费信源」中确认后启用。</p>')};
 function viewForm(){const v=activeView()||{name:'',type:state.filter,include:state.query?[state.query]:[],projectIds:state.project?[state.project]:[]};showForm(`${formTitle('我的情报视图')}<p>同一字段内满足任意一项，不同字段同时满足；关键词按文字匹配，不执行正则。</p><form id="personal-view-form"><label class="field">名称<input name="name" required maxlength="40" value="${escapeHtml(v.name||'')}"></label><label class="field">类型<select name="type">${[['all','全部'],['news','资讯'],['market','市场异动'],['combo','组合提醒']].map(([k,n])=>`<option value="${k}" ${k===(v.type||'all')?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">包含任一关键词<input name="include" value="${escapeHtml((v.include||[]).join(', '))}"></label><label class="field">排除任一关键词<input name="exclude" value="${escapeHtml((v.exclude||[]).join(', '))}"></label><label class="field">类别（逗号分隔）<input name="topics" placeholder="安全风险, 产品进展" value="${escapeHtml((v.topics||[]).join(', '))}"></label><label class="field">信源类型<select name="channels" multiple>${[['official','官网'],['x','官方 X'],['team','团队'],['opennews','媒体/聚合'],['subscription','项目订阅'],['kol','讨论者']].map(([k,n])=>`<option value="${k}" ${v.channels?.includes(k)?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">指定项目（不选代表所有关注）<select name="projectIds" multiple>${catalog.filter(p=>state.projects.includes(p.id)).map(p=>`<option value="${p.id}" ${v.projectIds?.includes(p.id)?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></label><label><input type="checkbox" name="savedOnly" ${v.savedOnly?'checked':''}> 仅收藏</label><label class="field">正文最少字符<input type="number" min="0" max="10000" name="minLength" value="${v.minLength||0}"></label><p class="form-error"></p><div class="modal-footer">${state.readerViews?.some(x=>x.id===v.id)?`<button type="button" class="secondary" data-delete-view="${v.id}">删除此视图</button>`:''}<button class="primary">保存视图</button></div></form>`);
  $('#personal-view-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),split=k=>String(f.get(k)||'').split(/[,，]/).map(s=>s.trim()).filter(Boolean);const custom=state.readerViews.some(x=>x.id===v.id);const item={id:custom?v.id:'view-'+Date.now(),name:String(f.get('name')).trim(),type:f.get('type'),include:split('include'),exclude:split('exclude'),topics:split('topics'),channels:f.getAll('channels'),projectIds:f.getAll('projectIds'),savedOnly:f.has('savedOnly'),minLength:Number(f.get('minLength'))};if(['include','exclude','topics'].some(k=>item[k].length>20||item[k].some(x=>x.length>100))||!custom&&state.readerViews.length>=30){e.target.querySelector('.form-error').textContent='最多 30 个视图，每项最多 20 个、每词 100 字';return}state.readerViews=[...state.readerViews.filter(x=>x.id!==item.id),item];chosen=item.id;persist();$('#form-dialog').close();render()});
 }
 function feedbackForm(id){const e=events.find(x=>x.id===Number(id));if(!e)return;showForm(`${formTitle('调整这条资讯')}<p>仅改变阅读展示，不删除原始资讯，也不修改后台提醒规则。所有操作可在「降噪管理」撤销。</p><label class="field">项目范围<select id="feedback-project">${(e.projectIds||[e.p]).map(pid=>`<option value="${pid}" ${state.project===pid?'selected':''}>${escapeHtml(catalog.find(p=>p.id===pid)?.name||pid)}</option>`).join('')}</select></label><div class="feedback-options"><button class="secondary" data-feedback-kind="unrelated" data-feedback-id="${e.id}">与选中项目无关</button><small>移除这条原文与选中项目的关联，其他项目仍可保留。</small><button class="secondary" data-feedback-kind="topic" data-feedback-id="${e.id}">减少此类内容</button><small>折叠选中项目的「${escapeHtml(e.topic||e.providerKind||'项目资讯')}」类别。</small><button class="secondary" data-feedback-kind="source" data-feedback-id="${e.id}">静音此来源</button><small>在所有项目中折叠「${escapeHtml(e.source)}」。</small></div>`)}
 function manageFeedback(){showForm(`${formTitle('降噪管理')}<p>撤销后内容重新参与正常筛选。不会删除或更改后台已保存的提醒。</p>${(state.readerFeedback||[]).map(f=>`<p>${escapeHtml({unrelated:'与项目无关',topic:'减少类别',source:'静音来源'}[f.kind])} · ${escapeHtml(f.value||f.eventKey)} ${f.projectId?' · '+escapeHtml(catalog.find(p=>p.id===f.projectId)?.name||f.projectId):''} <button class="text-button" data-undo-feedback="${f.id}">撤销</button></p>`).join('')||'<p>暂无个人降噪规则。</p>'}`)}
 async function manageSources(pid){await extension(pid,true);const x=extensionCache.get(pid)?.sources||{};showForm(`${formTitle('免费信源与额度设置')}<p>原生 RSS / Atom、Medium、Mirror、GitHub 仓库链接可直接添加。Telegram 需配置 RSSHub。官网发现仅为候选，不代表身份核验；确认后每半小时采集。</p><button class="secondary" data-discover-sources="${pid}">探测官网信源</button><button class="text-button" data-sources-manage="${pid}">刷新探测结果</button><p class="module-note">${x.discovering?'探测中，请稍后刷新':x.discoveryStatus==='error'?'官网探测失败，可手动添加':x.discoveredAt?'最近探测 '+formatTime(x.discoveredAt):'尚未探测'}</p>${(x.candidates||[]).map((c,i)=>`<div class="source-row"><a href="${escapeHtml(safeUrl(c.evidence))}" target="_blank" rel="noopener noreferrer">${escapeHtml(c.kind)}</a><small>${escapeHtml(c.url)}</small><button class="text-button" data-confirm-source="${i}" data-source-project="${pid}">确认并订阅</button></div>`).join('')}<h3>已确认订阅</h3>${(x.sources||[]).map(s=>`<div class="source-row">${escapeHtml(s.label)} · ${!s.enabled?'暂停':s.status==='ok'?'正常':s.status==='error'?'查询失败，等待退避重试':'等待采集'}<small>${escapeHtml(s.url)} · 最近成功 ${formatTime(s.lastSuccessAt)}</small><button class="text-button" data-source-toggle="${s.id}" data-source-project="${pid}">${s.enabled?'暂停':'恢复'}</button></div>`).join('')||'<p>尚未添加订阅源。</p>'}<form id="source-add-form"><label class="field">来源名称<input name="label" maxlength="80" required></label><label class="field">RSS / 项目博客 / GitHub 仓库 URL<input name="url" type="url" required placeholder="https://"></label><p class="form-error"></p><button class="primary">验证并添加</button></form><hr><label><input type="checkbox" id="source-economy" data-source-project="${pid}" ${x.economy?'checked':''}> 免费源优先，减少 OpenNews 关键词查询</label><p class="module-note">仅在已确认免费源最近一小时采集成功时跳过关键词补充查询；失败自动恢复。币种新闻、X、链上和交易所事件继续采集。免费源内容可能不完整。</p>`);
  $('#source-add-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await postAPI('/api/extensions/source',{projectId:pid,...Object.fromEntries(new FormData(e.target))});await manageSources(pid)}catch(err){e.target.querySelector('.form-error').textContent=err.message;b.disabled=false}});
 }
 function calendarForm(pid){showForm(`${formTitle('录入融资披露')}<form id="calendar-form"><label class="field">类型<select name="kind"><option value="funding">已披露融资</option></select></label><label class="field">标题<input name="title" maxlength="120" required></label><label class="field">时间（本机时区）<input name="date" type="datetime-local" required></label><label class="field">来源链接<input name="url" type="url" required placeholder="https://"></label><p class="module-note">记录已披露的历史融资和原文链接，不预测未来融资。</p><p class="form-error"></p><button class="primary">保存日程</button></form>`);$('#calendar-form').addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await postAPI('/api/extensions/calendar',{...d,projectId:pid,date:new Date(d.date).toISOString()});$('#form-dialog').close();await extension(pid,true);await refreshLive()}catch(err){e.target.querySelector('.form-error').textContent=err.message}})}
 document.addEventListener('change',async e=>{if(e.target.id==='reader-view'){chosen=e.target.value;render()}if(e.target.id==='source-economy'){try{await postAPI('/api/extensions/source-action',{projectId:e.target.dataset.sourceProject,action:'economy',enabled:e.target.checked});toast('额度策略已保存')}catch(err){e.target.checked=!e.target.checked;toast(err.message)}}});
 document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;const d=b.dataset;
  try{
   if('newView'in d)viewForm();
   if(d.deleteView){state.readerViews=state.readerViews.filter(x=>x.id!==d.deleteView);chosen='';persist();$('#form-dialog').close();render()}
   if(d.feedbackEvent)feedbackForm(d.feedbackEvent);
   if('manageFeedback'in d)manageFeedback();
   if(d.feedbackKind){const e=events.find(x=>x.id===Number(d.feedbackId));if(state.readerFeedback.length>=300){toast('降噪规则已达 300 条，请先撤销旧规则');return}const f={id:'feedback-'+Date.now(),kind:d.feedbackKind,projectId:d.feedbackKind==='source'?'':$('#feedback-project').value,eventKey:e.url||String(e.id),value:d.feedbackKind==='source'?(e.sourceUrl||e.source):d.feedbackKind==='topic'?(e.topic||e.providerKind||'项目资讯'):e.title.slice(0,100)};state.readerFeedback.push(f);persist();$('#form-dialog').close();render();toast('已调整，可在降噪管理撤销')}
   if(d.undoFeedback){state.readerFeedback=state.readerFeedback.filter(f=>f.id!==d.undoFeedback);persist();render();manageFeedback()}
   if(d.sourcesManage)await manageSources(d.sourcesManage);
   if(d.discoverSources){b.disabled=true;await postAPI('/api/extensions/discover',{projectId:d.discoverSources});toast('已开始探测，稍后点击刷新探测结果');b.disabled=false}
   if(d.confirmSource){const c=extensionCache.get(d.sourceProject).sources.candidates[Number(d.confirmSource)];b.disabled=true;await postAPI('/api/extensions/source',{projectId:d.sourceProject,url:c.url,label:c.kind});await manageSources(d.sourceProject)}
   if(d.sourceToggle){await postAPI('/api/extensions/source-action',{projectId:d.sourceProject,id:d.sourceToggle,action:'toggle'});await manageSources(d.sourceProject)}
   if(d.calendarAdd)calendarForm(d.calendarAdd);
   if(d.calendarRemove){await postAPI('/api/extensions/calendar-remove',{projectId:state.project,id:d.calendarRemove});await extension(state.project,true);await refreshLive()}
   if(d.calendarMap){const pid=d.calendarMap,x=extensionCache.get(pid)||{};showForm(`${formTitle('关联 DefiLlama 融资数据')}<p>API 需要本机配置 DEFILLAMA_API_KEY。用确切标识匹配，不使用代币简称猜测。融资只展示已披露历史。</p><form id="calendar-map-form"><label class="field">DefiLlama 协议 ID（融资）<input name="protocolId" value="${escapeHtml(x.calendarProtocolId||'')}" placeholder="数字 ID 或 parent#名称"></label><p class="form-error"></p><button class="primary">保存关联</button></form>`);$('#calendar-map-form').addEventListener('submit',async e=>{e.preventDefault();try{await postAPI('/api/extensions/mapping',{projectId:pid,...Object.fromEntries(new FormData(e.target))});$('#form-dialog').close();await extension(pid,true)}catch(err){e.target.querySelector('.form-error').textContent=err.message}})}
  }catch(err){b.disabled=false;toast(err.message)}
 });
 render();
}
